script:
(function(){
  var all = document.querySelectorAll("*");
  for (var i = 0; i < all.length; i++) {
    var fk = null;
    var ks = Object.keys(all[i]);
    for (var j = 0; j < ks.length; j++) {
      if (ks[j].indexOf("__reactFiber") === 0) {
        fk = ks[j];
        break;
      }
    }
    if (!fk) continue;
    var f = all[i][fk];
    var t = 0;
    while (f && t < 60) {
      t++;
      if (f.memoizedState) {
        var curState = f.memoizedState;
        var d = 0;
        while (curState && d < 25) {
          d++;
          try {
            var lrs = curState.queue ? curState.queue.lastRenderedState : undefined;
            var lrsStr = lrs !== undefined ? JSON.stringify(lrs) : null;
            if (lrsStr && lrsStr.indexOf("one_liner_title") >= 0 && curState.queue && curState.queue.dispatch) {
              var dispatch = curState.queue.dispatch;
              // Create action to mark one_liner_title as valid
              var action = {
                type: "SET_FIELD_VALUE",
                payload: {
                  stepId: 1,
                  fieldName: "one_liner_title",
                  value: "ATS Resume Writer",
                  isValid: true,
                  isDirty: true
                }
              };
              try {
                return JSON.stringify({found:true, action: action, dispatchType: typeof dispatch, willDispatch: true});
              } catch(e) {
                return JSON.stringify({found:true, err: e.message});
              }
            }
          } catch(e) {}
          if (curState.next) curState = curState.next; else break;
        }
      }
      if (f.return) f = f.return; else break;
    }
  }
  return "not found";
})()
